-- Importação histórica de retiradas (chaves e ferramentas) fornecida pelo usuário.
-- Liberador fixo: Nicolas Gustavo da Silva. Horário nominal 08:00 (retirada) / 17:00 (recebimento), pois a planilha só tinha a data.

SELECT 'Arlindo', '11000000000', (SELECT id_empresa FROM empresas WHERE nm_empresa = 'Cury'), (SELECT id_cargo FROM cargos WHERE nm_cargo = 'Pedreiro'), (SELECT id_permissao FROM permissoes WHERE nm_permissao = 'Retirar')
WHERE NOT EXISTS (SELECT 1 FROM users WHERE nm_user = 'Arlindo');


